#!/usr/bin/env python3
"""Keep release gates when packaging an official Alpine Cargo ELF locally."""
import argparse
from pathlib import Path
import re
import sys


ALLOCATOR_GATE = "RUN --network=none /out/cmaeg --allocator-self-test"
STRIP_BINARY = "RUN --network=none strip --strip-all /out/cmaeg"
RUNTIME_BINARY = "COPY --from=build /out/cmaeg /usr/local/bin/cmaeg"
MEDIA_REPORT = (
    "COPY --from=media-self-test /tmp/media-self-test.txt "
    "/usr/local/share/cmaeg/media-self-test.txt"
)
SANDBOX_GATE = """RUN --network=none <<'SANDBOX_CHECK'
set -eu
case "${TARGETARCH}" in
  amd64) /out/cmaeg --media-sandbox-check ;;
  *) set +e; /out/cmaeg --media-sandbox-check; status=$?; set -e; test "${status}" -eq 125 ;;
esac
SANDBOX_CHECK"""


def require_once(text, expected):
    if text.splitlines().count(expected) != 1:
        raise ValueError(f"missing or changed release instruction: {expected}")


def stages(dockerfile):
    matches = list(re.finditer(r"^FROM .+ AS ([\w-]+)$", dockerfile, re.MULTILINE))
    if len(matches) != len(re.findall(r"^FROM\s", dockerfile, re.MULTILINE)):
        raise ValueError("every release stage must have an explicit name")
    result = {}
    for index, match in enumerate(matches):
        name = match[1]
        if name in result:
            raise ValueError(f"duplicate release stage: {name}")
        end = matches[index + 1].start() if index + 1 < len(matches) else len(dockerfile)
        lines = dockerfile[match.start():end].splitlines()
        # Comments introducing the next stage must not describe a removed stage.
        while lines and (not lines[-1].strip() or lines[-1].startswith("#")):
            lines.pop()
        result[name] = "\n".join(lines) + "\n"
    if not result or list(result)[-1] != "runtime":
        raise ValueError("runtime must be the final release stage")
    return result


def render(dockerfile):
    source = stages(dockerfile)
    if not {"build", "media-self-test", "runtime"} <= source.keys():
        raise ValueError("missing build, media-self-test or runtime stage")
    build, media, runtime = (source[name] for name in ("build", "media-self-test", "runtime"))
    require_once(build, "FROM rust:1.96.1-alpine AS build")
    # Accept the historical recipe and the equivalent guarded Cargo invocation.
    cargo_build = "cargo build --release --locked --bin cmaeg \\"
    if len(re.findall(r"(?m)^    (?:&& )?" + re.escape(cargo_build) + r"$", build)) != 1:
        raise ValueError("missing or changed release instruction: " + cargo_build)
    copy = "    && cp /build/target/release/cmaeg /out/cmaeg"
    if len(re.findall(r"(?m)^" + re.escape(copy) + r"(?: \\)?$", build)) != 1:
        raise ValueError("missing or changed release instruction: " + copy)
    if "zig" in build.lower():
        raise ValueError("local release requires the official Alpine Cargo build")
    require_once(build, STRIP_BINARY)
    require_once(build, ALLOCATOR_GATE)
    if build.index(STRIP_BINARY) > build.index(ALLOCATOR_GATE):
        raise ValueError("stripping must precede the allocator gate")
    if build.count(SANDBOX_GATE) != 1:
        raise ValueError("missing or changed release sandbox gate")
    if build.index(SANDBOX_GATE) < build.index(ALLOCATOR_GATE):
        raise ValueError("allocator gate must precede the sandbox gate")
    gates = build[build.index(ALLOCATOR_GATE):]
    # A later instruction could replace the qualified ELF. Only the two known
    # gates and their comments belong in this stage; recipe changes need review.
    extra = gates.replace(ALLOCATOR_GATE, "", 1).replace(SANDBOX_GATE, "", 1)
    if any(line.strip() and not line.startswith("#") for line in extra.splitlines()):
        raise ValueError("unexpected instruction after the compiled ELF")
    for instruction in (
        RUNTIME_BINARY,
        "RUN --network=none <<'MEDIA_SELF_TEST'",
        "    status=0",
        "    CMAEG_MEDIA_FFMPEG_DIR=/opt/ffmpeg/bin /usr/local/bin/cmaeg \\",
        "      --media-self-test /opt/cmaeg-media-fixtures > /tmp/media-self-test.txt || status=$?",
        '    test "${status}" -eq 0',
        "COPY api/crates/cmaeg/tests/fixtures/media/ /opt/cmaeg-media-fixtures/",
        "USER 10001:10001",
    ):
        require_once(media, instruction)
    for instruction in (RUNTIME_BINARY, MEDIA_REPORT, 'ENTRYPOINT ["/usr/local/bin/cmaeg"]'):
        require_once(runtime, instruction)
    base = re.fullmatch(r"FROM ([\w.:/@-]+) AS runtime", runtime.splitlines()[0])
    if not base:
        raise ValueError("unsupported runtime base")
    # Use the runtime OS for the supplied ELF; retain the selected source's
    # complete sandbox/media/runtime stages instead of an incident snapshot.
    return (
        "# syntax=docker/dockerfile:1\n"
        "# Generated by .github/scripts/prepare-cmaeg-release-dockerfile.py.\n"
        "# Input ELF must come from the official native Alpine Cargo build.\n"
        "FROM scratch AS dependencies\nCOPY dependencies/ /\n"
        "FROM dependencies AS ffmpeg-build\n"
        f"FROM {base[1]} AS build\nARG TARGETARCH\n"
        "RUN apk add --no-cache binutils\n"
        "COPY native/cmaeg /out/cmaeg\n"
        f"{STRIP_BINARY}\n"
        f"{gates}\n{media}\n{runtime}"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True, type=Path, help="exact selected repository source")
    parser.add_argument("--output", required=True, type=Path, help="prepared context Dockerfile")
    args = parser.parse_args()
    source = args.source / "api/crates/cmaeg/Dockerfile"
    try:
        if source.resolve() == args.output.resolve():
            raise ValueError("output must not replace the source Dockerfile")
        rendered = render(source.read_text())
        args.output.write_text(rendered)
    except (OSError, ValueError) as error:
        print(f"local EG release recipe refused: {error}", file=sys.stderr)
        return 1
    print(f"local EG release recipe ready: {args.output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
